void handle_vm_cmdReplyClientDoubtInfo(GameClient& cl, const uint8_t* body, size_t len)
{
    if (len < 2) return;
    uint8_t type = body[0];
    uint8_t nLen = body[1];
    if (2 + nLen + 2 > len) return;
    const uint8_t* name = body + 2;
    size_t off = 2 + nLen;
    uint16_t mLen = rd16be(body, off);
    if (off + 2 + mLen > len) return;
